/**
 * Type helper pour accéder aux couleurs avec autocomplétion
 */
export type ColorToken = keyof typeof color;

/**
 * Helper pour générer des variantes avec opacité.
 *
 * Supporte hex, rgba() ET les CSS vars (themeColor.* = `var(--theme-x)`).
 * Pour une CSS var (non résoluble en JS), bascule sur `color-mix()` qui fait
 * l'équivalent côté navigateur. AVANT 2026-06-07, une CSS var produisait
 * `rgba(NaN, NaN, NaN, x)` = CSS invalide silencieusement DROPPÉ par le
 * navigateur (fond/bordure fantômes — incident bouton "sélection multiple"
 * DossiersPage, ~50 fichiers affectés). Ne JAMAIS réintroduire le path NaN.
 */
export const withOpacity = (colorValue: string, opacity: number): string => {
  /* UN JETON ABSENT CRASHAIT ICI (2026-09-12). `.includes()` sur `undefined`
     lève, et c'est le point de passage le plus fréquenté du front — 9 405 appels.
     TypeScript couvre les jetons littéraux ; 119 appels passent une prop de
     styled OPTIONNELLE sans repli. Mesures et les neuf cas, dont l'opacité zéro
     qui n'est PAS une absence : `__tests__/with-opacity-jeton-absent.test.ts`. */
  if (colorValue == null || colorValue === "") {
    if (import.meta.env.DEV) {
      // eslint-disable-next-line no-console
      console.error(
        "[withOpacity] couleur absente — un jeton a été renommé ou une prop " +
          "optionnelle n'a pas été passée. Rendu : transparent.",
      );
    }
    return "transparent";
  }
  // Handle CSS vars / non-parsable colors (var(--x), color-mix(...)) —
  // delegate alpha compositing to the browser via color-mix.
  if (colorValue.includes("var(") || colorValue.includes("color-mix(")) {
    return `color-mix(in srgb, ${colorValue} ${opacity * 100}%, transparent)`;
  }
  // Handle rgba() input — extract RGB and replace alpha
  const rgbaMatch = colorValue.match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);
  if (rgbaMatch) {
    return `rgba(${rgbaMatch[1]}, ${rgbaMatch[2]}, ${rgbaMatch[3]}, ${opacity})`;
  }
  // Handle hex input
  const hex = colorValue.replace("#", "");
  const r = parseInt(hex.substring(0, 2), 16);
  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${opacity})`;
};

/**
 * Helper pour générer un focus ring accessible
 */
export const getFocusRing = (colorHex: string = color.primary) => ({
  outline: `var(--border-medium) solid ${withOpacity(colorHex, 0.3)}`,
  outlineOffset: "2px",
});
