/**
 * Le point d'entrée « deck seul » — un deck de présentation, sans l'application.
 *
 * Construit par `vite.deck.config.ts` (le même pipeline de transformation que
 * l'application : mêmes alias, même plugin styled-components), publié par
 * `bash scripts/publier-deck.sh <slug>`. Le deck à monter est choisi au build
 * (`VITE_DECK_SLUG`) dans le registre `decks-publiables.ts`.
 *
 * Ce qu'il garde de l'application : les feuilles globales (variables, polices,
 * corps), les variables de thème, le mouvement réduit respecté. Ce qu'il laisse :
 * le routeur, les requêtes, l'authentification, Ant — un deck n'en a pas besoin.
 */
import "@/shared/design-tokens/variables.css";
import "./app/globals.css";

import { MotionConfig } from "framer-motion";
import { lazy, StrictMode, Suspense } from "react";
import { createRoot } from "react-dom/client";
import { createGlobalStyle } from "styled-components";

import { px } from "@/shared/design-tokens/scale";
import { GlobalThemeStyle } from "@/shared/design-tokens/theme-vars";
import { DECKS_PUBLIABLES } from "@/shared/presentation-engine/decks-publiables";

/* La base de l'application (`main.tsx`) : la racine à 80 % (SCALE_FACTOR) et une
   page sans marge — ce qu'un deck lit de l'application. */
const StyleDuDeck = createGlobalStyle`
  html {
    font-size: ${px(16)};
  }
  body {
    margin: 0;
    background: #050b16;
  }
`;

/* Le deck est celui du build (`VITE_DECK_SLUG`). Son aperçu local passe par le
   showroom de l'application (`/showroom/<entrée du deck>`) : le conteneur du front
   ne monte que `index.html`, et un `deck.html` y retombe sur la page introuvable
   de l'application (vu le 2026-10-14). */
const slug = import.meta.env.VITE_DECK_SLUG as string | undefined;
const deck = slug ? DECKS_PUBLIABLES[slug] : undefined;

if (!deck) {
  throw new Error(
    `Deck inconnu : « ${slug ?? "(aucun)"} » — VITE_DECK_SLUG doit nommer une entrée de decks-publiables.ts`,
  );
}

document.title = deck.titre;
document.body.setAttribute("data-theme", deck.theme ?? "light");

const Deck = lazy(deck.charger);

const racine = document.getElementById("root");
if (!racine) throw new Error("Le conteneur #root manque à deck.html");

createRoot(racine).render(
  <StrictMode>
    <MotionConfig reducedMotion="user">
      <StyleDuDeck />
      <GlobalThemeStyle />
      <Suspense fallback={null}>
        <Deck />
      </Suspense>
    </MotionConfig>
  </StrictMode>,
);
