/**
 * Les decks qu'on peut publier hors de l'application — le registre que lit le
 * build « deck seul » (`front/deck.html`, `vite.deck.config.ts`) et la commande
 * `bash scripts/publier-deck.sh <slug>`.
 *
 * Un deck publié est un SITE STATIQUE : le deck, le moteur de présentation et le
 * moteur d'animation, sans l'application autour, servi à
 * `https://juris-power.github.io/decks/<slug>/`. Il se met à jour depuis la
 * session de travail, sans la cascade de déploiement (demande de William,
 * 2026-10-14 : « un lien direct entre ma session de travail et ma présentation
 * en ligne »). Il ne lit rien au serveur : une donnée qu'il montre est figée au
 * build.
 *
 * Un deck n'entre ici qu'avec son accord de publication : ce qui y figure est
 * PUBLIC (dépôt et pages publics).
 */
import type { ComponentType } from "react";

export interface DeckPubliable {
  /** Le titre de l'onglet. */
  readonly titre: string;
  /** Le deck lui-même — l'export par défaut de son module. */
  readonly charger: () => Promise<{ default: ComponentType }>;
  /** Le thème de la page (`light` par défaut). Un deck tout de nuit prend `dark` :
   *  le fond du moteur, qui paraît entre deux planches, suit le thème. */
  readonly theme?: "light" | "dark";
}

export const DECKS_PUBLIABLES: Readonly<Record<string, DeckPubliable>> = {
  /* Le showroom du moteur d'animation : l'essai de bout en bout de la chaîne de
     publication (2026-10-14), avant le premier vrai deck. */
  moteur: {
    titre: "Juris-Connect — le moteur d'animation",
    charger: () => import("@/shared/presentation-engine/showroom/MotionShowroom"),
  },
  /* La Pitch Night de l'Incubateur du Barreau de Paris (15 octobre 2026) — Raoul
     Delpech au pupitre, trois minutes ; accord de publication de William le
     2026-10-14 (« OK avec tout GO »). */
  "pitch-night-2026": {
    titre: "Juris-Connect — Pitch Night 2026",
    charger: () => import("@/features/_lab-imports/pitch-night-2026/parcours"),
    theme: "dark",
  },
};
