/**
 * Design System - Global Scale Factor
 *
 * Charte Officielle Juris-Power / MEDIANE
 *
 * HISTORIQUE:
 * L'interface utilisait `zoom: 0.8` sur <html> pour un rendu compact.
 * Ce zoom causait des bugs (drag-and-drop, coordonnees, video, calendar).
 * Il a ete remplace par ce systeme de scale factor applique via design tokens.
 *
 * SCALE_FACTOR = 0.8 produit un rendu compact identique au zoom 0.8
 * sans les effets de bord sur getBoundingClientRect, offsetX/Y, etc.
 *
 * Toutes les valeurs dimensionnelles passent par px(), num(), rem() ou shadow().
 * Les styled-components utilisent ${px(N)} (converti par codemod-px-to-scale.mjs).
 * Les tokens Ant Design utilisent num(N) dans main.tsx.
 * Les CSS variables sont overridees dans GlobalStyle via px()/shadow().
 */

// ============================================
// SCALE FACTOR — Unique source de verite
// ============================================

/**
 * Facteur d'echelle global.
 *
 * Controle la densite de toute l'interface :
 * - 0.80 = compact (equivalent visuel de la prod avec zoom: 0.8)
 * - 0.85 = legerement plus aere
 * - 1.00 = taille native Ant Design / navigateur
 *
 * Ce facteur est applique automatiquement sur :
 * - Ant Design tokens (via num() dans main.tsx)
 * - CSS custom properties (via px() dans GlobalStyle)
 * - Styled-components (via px() dans les template literals)
 * - Shadows (via shadow() dans color.ts)
 *
 * Pour changer la densite de l'UI : modifier UNIQUEMENT cette valeur.
 */
export const SCALE_FACTOR = 0.8;

// ============================================
// HELPERS
// ============================================

/**
 * Convertit une valeur de base (en pixels) en string CSS scalee.
 *
 * @param base - Valeur de design de base en pixels (ex: 16)
 * @returns String CSS avec le facteur applique (ex: '13px')
 *
 * @example
 * px(16)  // → '13px'  (16 × 0.8 = 12.8, arrondi → 13)
 * px(4)   // → '3px'   (4 × 0.8 = 3.2, arrondi → 3)
 * px(32)  // → '26px'  (32 × 0.8 = 25.6, arrondi → 26)
 */
export const px = (base: number): string => `${Math.round(base * SCALE_FACTOR)}px`;

/**
 * Convertit une valeur de base en nombre scale (sans unite).
 * Utile pour les tokens Ant Design qui attendent un number.
 *
 * @param base - Valeur de design de base (ex: 14)
 * @returns Nombre arrondi avec le facteur applique (ex: 11)
 *
 * @example
 * num(14)  // → 11  (fontSize)
 * num(32)  // → 26  (controlHeight)
 * num(6)   // → 5   (borderRadius)
 */
export const num = (base: number): number => Math.round(base * SCALE_FACTOR);

/**
 * Convertit une valeur rem de base en string CSS rem scalee.
 * Utile pour la typographie fluide (clamp) et les font-sizes relatifs.
 *
 * @param base - Valeur rem de base (ex: 1.75)
 * @returns String CSS rem scalee (ex: '1.4rem')
 *
 * @example
 * rem(1.75)  // → '1.4rem'   (1.75 × 0.8)
 * rem(3)     // → '2.4rem'   (3 × 0.8)
 * rem(0.875) // → '0.7rem'   (0.875 × 0.8)
 */
export const rem = (base: number): string => {
  const scaled = Math.round(base * SCALE_FACTOR * 1000) / 1000;
  return `${scaled}rem`;
};

/**
 * Scale une valeur vw. Avec `zoom: 0.8`, les unites viewport etaient
 * aussi zoomees (5vw rendait visuellement 4vw). Pour conserver le meme
 * rendu sans zoom, on multiplie les vw par SCALE_FACTOR.
 *
 * @param base - Valeur vw de base (ex: 5)
 * @returns String CSS vw scalee (ex: '4vw')
 *
 * @example
 * vw(5)   // → '4vw'    (5 × 0.8)
 * vw(3.5) // → '2.8vw'  (3.5 × 0.8)
 */
export const vw = (base: number): string => {
  const scaled = Math.round(base * SCALE_FACTOR * 100) / 100;
  return `${scaled}vw`;
};

/**
 * Genere une expression CSS clamp() avec toutes les valeurs scalees.
 * Indispensable pour la typographie fluide.
 *
 * Avec `zoom: 0.8`, le navigateur scalait uniformement rem, vw, et px
 * dans les clamp(). Sans zoom, on doit scaler chaque composante manuellement.
 *
 * @param minRem  - Taille minimale en rem (ex: 1.75)
 * @param vwCoeff - Coefficient viewport-width (ex: 5 pour 5vw)
 * @param remAdd  - Ajout rem dans la partie preferred (ex: 0.5)
 * @param maxRem  - Taille maximale en rem (ex: 3)
 * @returns String CSS clamp() scalee
 *
 * @example
 * // Base : clamp(1.75rem, 5vw + 0.5rem, 3rem)
 * fluidScale(1.75, 5, 0.5, 3)
 * // → 'clamp(1.4rem, 4vw + 0.4rem, 2.4rem)'
 */
export const fluidScale = (
  minRem: number,
  vwCoeff: number,
  remAdd: number,
  maxRem: number,
): string => {
  const sMin = Math.round(minRem * SCALE_FACTOR * 1000) / 1000;
  const sVw = Math.round(vwCoeff * SCALE_FACTOR * 100) / 100;
  const sAdd = Math.round(remAdd * SCALE_FACTOR * 1000) / 1000;
  const sMax = Math.round(maxRem * SCALE_FACTOR * 1000) / 1000;
  return `clamp(${sMin}rem, ${sVw}vw + ${sAdd}rem, ${sMax}rem)`;
};

/**
 * Scale les valeurs de pixel dans une expression de box-shadow.
 * Les couleurs/rgba ne sont pas modifiees, seuls les offsets et blurs le sont.
 *
 * @param shadow - Expression box-shadow CSS complete
 * @returns Shadow avec les px scales
 *
 * @example
 * shadow('0 2px 8px rgba(0,0,0,0.15)')
 * // → '0 2px 6px rgba(0,0,0,0.15)'
 *
 * shadow('0 4px 12px rgba(0,0,0,0.15)')
 * // → '0 3px 10px rgba(0,0,0,0.15)'
 */
export const shadow = (value: string): string =>
  value.replace(/(\d+)px/g, (_, n) => {
    const scaled = Math.round(Number(n) * SCALE_FACTOR);
    return `${scaled}px`;
  });

// ============================================
// BORDER WIDTH — Sub-pixel precision
// ============================================

/**
 * Border width avec precision sub-pixel.
 *
 * `px()` arrondit a l'entier, ce qui annule le scaling pour 1-2px :
 *   px(1) = Math.round(0.8) = 1px  (pas de changement !)
 *   px(2) = Math.round(1.6) = 2px  (pas de changement !)
 *
 * Avec `zoom: 0.8`, les bordures rendaient a 0.8px/1.6px visuellement.
 * `borderPx()` preserve un decimal pour reproduire ce rendu sur Retina.
 *
 * @param base - Epaisseur de bordure de base en pixels (ex: 1)
 * @returns String CSS sub-pixel (ex: '0.8px')
 *
 * @example
 * borderPx(1)  // → '0.8px'  (equivaut a 1px * zoom:0.8)
 * borderPx(2)  // → '1.6px'  (equivaut a 2px * zoom:0.8)
 * borderPx(3)  // → '2.4px'
 */
export const borderPx = (base: number): string => {
  const scaled = Math.round(base * SCALE_FACTOR * 10) / 10;
  return `${scaled}px`;
};

// ============================================
// IDENTITY — Valeurs qui NE doivent PAS scaler
// ============================================

/**
 * Marqueur pour les valeurs qui ne doivent PAS etre scalees.
 * Utiliser pour la lisibilite et documenter l'intention.
 *
 * @example
 * border: ${fixed(1)}px solid ${themeColor.border};  // Bordure fine, JAMAIS scalee
 * z-index: ${fixed(100)};                       // Pas dimensionnel
 */
export const fixed = (value: number): number => value;

/**
 * Guide : quand NE PAS utiliser px() / num() / rem()
 *
 * - Couleurs : jamais dimensionnelles
 * - Pourcentages : '50%', '100%' — relatifs
 * - Breakpoints media queries : le viewport reel ne change pas
 * - Z-index : pas dimensionnel
 * - Line-height (ratio) : 1.5, 1.6 — ratio, pas dimension
 * - Border-width : utiliser borderPx(N) ou var(--border-thin) / var(--border-medium)
 *   px(1)=1px est VISUELLEMENT plus epais que l'ancien zoom:0.8 (0.8px)
 * - Opacity : 0-1 — pas dimensionnel
 * - Transition durations : 150ms, 300ms — temporel, pas spatial
 * - border: 0 / margin: 0 — zero reste zero
 */

