/**
 * Design System - Theme Variables (CSS Custom Properties)
 *
 * Ces CSS variables basculent automatiquement entre light/dark
 * en fonction de l'attribut `data-theme` sur document.body (set par ThemeContext).
 *
 * Usage dans styled-components :
 *   import { themeColor } from '@/shared/design-tokens/theme-vars';
 *   const Card = styled.div`background: ${themeColor.bg};`;
 *
 * IMPORTANT :
 * - themeColor = valeurs qui CHANGENT avec le theme (surfaces, textes, bordures)
 * - color = valeurs FIXES (brand: primary, secondary, success, error, warning)
 *   Les brand colors ne changent pas entre light/dark → continuer a utiliser color.*
 */

import { createGlobalStyle } from "styled-components";
import { color, withOpacity } from "./color";

/**
 * La table des paires `[light, dark]`, exportée pour être VÉRIFIABLE.
 *
 * `themeColor.X` ne rend qu'une chaîne `var(--theme-X)` : aucun banc ne peut en
 * tirer un ratio de contraste. Sans cet export, un test qui veut contrôler la
 * lisibilité d'un token doit recopier ses deux valeurs — et une copie diverge de
 * l'original sans que rien ne rougisse, ce qui produit un banc vert gardant une
 * table qui n'existe plus.
 *
 * Lecture seule. Les composants continuent d'employer `themeColor`.
 */
export const themeMap = {
  // ============================================
  // BACKGROUNDS
  // ============================================
  bg: [color.background, color.backgroundDark],
  bgSecondary: [color.backgroundSecondary, color.backgroundSecondaryDark],
  bgTertiary: [color.backgroundTertiary, color.backgroundTertiaryDark],
  /* L'ECHELLE DE PROFONDEUR — `canvas` / `surface` / `subtle`.
     Trois roles nommes la ou le depot avait deux noms pour une couleur
     (`bgSecondary` et `gray50` = #F8F9FA) et quatre pour une autre en sombre
     (`inputGray`, `gray100`, `surface`, `backgroundTertiary` = #132235).
     `bgSecondary` et `gray50` restent en place : ils deviennent les ALIAS
     historiques de `canvas` — et la migration n'a PAS eu lieu.

     LE CHIFFRE AVEC SA POPULATION, faute de quoi il ne se compare a rien.
     Remesure du 2026-09-18, en OCCURRENCES (pas en lignes) sur tous les
     TypeScript de front/src, demo comprise, hors lab-imports, generated-api,
     design-tokens, bancs et histoires :
         themeColor.gray50       827 occ / 520 fichiers
         themeColor.bgSecondary  398 occ / 298 fichiers  → alias : 1 225 / 818
         themeColor.canvas        17 occ /  11 fichiers
     LES CHIFFRES D'AVANT NE SE RECONSTITUENT PAS : ni « 696 » (date du
     2026-09-11, ici meme) ni « 1 056 » plus bas ne sortent d'aucun des six
     perimetres essayes, qui donnent 1 171 a 1 320. On ne peut donc PAS dire si
     la dette a grossi, seulement qu'elle est la — et le commentaire remplace
     avait DEJA ete ecrit pour corriger un chiffre faux.
     Le pourquoi et les mesures vivent sur les tokens eux-memes (color.ts).

     ── `bgSecondary` VAUT DESORMAIS `canvas` (arbitrage William 2026-09-12) ──

     Un alias qui ne vaut pas ce qu'il aliase n'est pas un alias : c'est un
     second jeton qui attend de diverger. Il a divergé le 2026-09-05, quand le
     canvas est passe au froid sans que la chaine soit unifiee — et un fond de
     page s'est retrouve peint par deux valeurs a ΔE2000 2,66 l'une de l'autre,
     de meme clarte et de teintes differentes : une arete visible la ou elles se
     touchent. `color.backgroundSecondary` porte la valeur du canvas depuis, et
     ses 514 occurrences rendent la bonne couleur sans avoir bouge.

     ET `gray50` NE SUIT PAS : son nom dit un cran d'echelle de gris, pas un
     fond. C'est un accent INTERNE, dont l'ecrasante majorite des 862 usages
     — 827 par le role et 35 par le token fixe, meme population que plus haut,
     mesure du 2026-09-18 —
     vit sur du BLANC. La doctrine l'ecrit noir sur blanc — « ne PAS rechauffer
     gray50 par symetrie ». Mesures completes sur le token, dans color.ts. */
  canvas: [color.canvas, color.canvasDark],
  subtle: [color.subtle, color.subtleDark],
  surface: [color.surface, color.surfaceDark],
  /* LE SURVOL D'UNE LIGNE POSÉE SUR UNE SURFACE (2026-10-08, cran 3 du croquis
     `drive-avocat/croquis/2026-10-08-le-drive-au-clavier.md`). En clair, le
     gris de toujours (#F8F9FA). En sombre, un cran AU-DESSUS de la surface —
     #1A2D42, la valeur que l'étage sombre d'Ant donne à `Table.rowHoverBg` :
     `gray50` y vaut le sol (#0E1A28), et une ligne survolée s'y enfonçait
     au lieu de s'éclairer dès que la table est passée en `surface`. Opaque :
     une colonne épinglée ne laisse pas voir ce qui défile dessous. */
  surfaceHover: [color.gray50, color.surfaceElevatedDark],
  /** @deprecated alias post-merge lab/* — preferer `surface` ou `surfaceElevated` */
  surfaceAlt: [color.surfaceElevated, color.surfaceElevatedDark],
  surfaceElevated: [color.surfaceElevated, color.surfaceElevatedDark],
  bgElevated: [color.surfaceElevated, color.surfaceElevatedDark],
  surfaceOverlay: [color.surfaceOverlay, color.surfaceOverlayDark],
  /* Squelettes de chargement — le pic s'éloigne du fond dans les deux thèmes
     (plus sombre en clair, plus clair en sombre). Détail et mesures : color.ts. */
  skeleton: [color.skeleton, color.skeletonDark],
  skeletonPeak: [color.skeletonPeak, color.skeletonPeakDark],
  /* VERRE DÉPOLI d'une carte posée sur un panneau (backdrop-filter + lavis).
     Un voile BLANC fixe éclaircit un fond clair — c'est son rôle — mais posé
     sur un fond sombre il fabrique un gris pâle sous des encres prévues pour du
     sombre. Mesuré en production le 2026-08-21 sur /app/juris-ia/outils : les
     trois cartes de veille juridique rendaient #b7babf, et leur texte tombait à
     1,47-1,58:1 — visible sur capture, elles paraissent lavées à côté des
     cartes voisines. Le noir à 30 % assombrit d'une intensité comparable et
     rend 15,3:1 sur les titres, 6,6:1 sur le texte secondaire. */
  glassCard: [color.whiteAlpha70, color.blackAlpha30],
  inputBg: [color.inputGray, color.inputGrayDark],
  lightPrimary: [color.lightPrimary, color.lightPrimaryDark],

  // ============================================
  // TEXT
  // ============================================
  text: [color.inkBrand, color.inkBrandDark],
  textSecondary: [color.secondaryText, color.secondaryTextDark],
  textTertiary: [color.tertiaryText, color.tertiaryTextDark],
  textDisabled: [color.textDisabled, color.textDisabledDark],
  textPlaceholder: [color.textPlaceholder, color.textPlaceholderDark],

  // ============================================
  // BRAND-ON-SURFACE — couleur de marque utilisee comme TEXTE (encre)
  // ============================================
  // Une brand color posee en TEXTE sur une surface manque le ratio WCAG AA
  // 4.5:1 dans UN des deux modes, differemment selon la teinte :
  //   - sur blanc (light)  : success #00C0B5 -> 1.9:1, warning #F57C00 -> 2.7:1
  //     (trop CLAIRES) ; primary/error passent.
  //   - sur #0A1117 (dark) : primary #0077CC -> 3.9:1, error #C62828 -> 2.7:1,
  //     magenta #D14081 -> 4.3:1 (trop FONCEES) ; success/warning passent.
  // Chaque token combine donc la variante LISIBLE de chaque mode : version
  // *Text/*Dark (encre foncee) en light, version pleine/*Light (vive) en dark.
  // Toutes les valeurs reutilisent des tokens existants (aucune teinte inventee).
  // L'IDENTITE du statut (bordures/accents/fond teinte) reste `color.*` FIXE et
  // VIVE, identique light/dark — seul le LABEL texte bascule pour la lisibilite.
  // Cf agenda STATUS_COLORS (MeetingEventCard) : bordure = color.warning (vif),
  // texte = warningOnSurface (#A35200 light / #F57C00 dark).
  // MESURE 2026-07-21 (les ratios ci-dessous ne sont plus annotes a la main :
  // `theme-contrast.test.ts` les verifie). L'encre claire etait `color.primary`
  // #0077CC : conforme sur blanc pur (4,66) mais 4,42:1 sur backgroundSecondary,
  // le fond gris tres clair des cartes — juste sous la barre. primaryDark passe
  // a 7,06:1 sans changer la teinte de marque, seulement sa profondeur.
  primaryOnSurface: [color.primaryStrong, color.primaryLight],
  /* LE SURVOL D'UN LIEN, et il manquait (2026-09-20). `VerifiedSpan` posait
     `color.primaryStrong` en dur : 7,44 en clair, mais 2,55 sur le noir du
     produit et 2,33 sur la surface elevee — le survol y etait illisible. Le
     couple fonce en clair (18,13) et s'eclaircit en sombre (8,26 / 7,55), donc
     le geste se voit dans les deux sens. */
  primaryOnSurfaceHover: [color.primaryBlack, color.primaryLighter],
  /* LE FOND DE MARQUE — boutons, bandes, en-tetes de tiroir, notes bleues
     (arbitrage William, 2026-09-20 : « primaryStrong doit devenir le bleu
     principal utilise dans l'app »). Le blanc dessus rend 7,44 en clair et 4,66
     en sombre ; le fond se detache de sa page a 7,03 puis 4,07.
     LA BASCULE EST UNE NECESSITE, PAS UNE COMMODITE : `primaryStrong` laisse en
     theme sombre rend 2,55 contre le noir, sous le plancher de 3:1 — le bouton
     cesserait de se detacher de la page.

     NE PAS CONFONDRE AVEC `primaryOnSurface`, ET LE PIEGE EST QU'EN CLAIR ILS
     SONT LE MEME PIXEL : #005799 tous les deux. Ils ne divergent qu'en SOMBRE —
     #0077CC ici, #3399DD la-bas — et le blanc pose dessus y tombe alors a
     3,12:1, sous le plancher de 4,5, contre 4,66 avec le bon role. Un fond qui
     porte l'encre se voit donc PARFAITEMENT sur la moitie des ecrans : 15
     occurrences ont survecu ainsi jusqu'au 2026-09-21.
     La question qui tranche : *est-ce que je peins une surface, ou ce qui
     s'ecrit dessus ?* `Surface` peint, `OnSurface` s'ecrit. */
  primarySurface: [color.primaryStrong, color.primary], // 7,06:1 / 5,2:1
  // Encre d'IDENTITE des surfaces publiques — le navy du nom de l'avocat, du
  // titre de son cabinet, de l'onglet actif de sa vitrine (role `identity` de
  // `public-surface-roles`). Ce role valait `color.primaryBlack` EN DUR, donc
  // #0B1627 quel que soit le theme : mesure du 2026-08-21 sur la capture sombre
  // de la fiche publique, **1,02:1** sur la carte — le nom de l'avocat etait
  // litteralement invisible, et le libelle de l'onglet actif avait disparu.
  // Le clair est INCHANGE (primaryBlack, 18,13:1) ; le sombre prend primaryLight
  // (4,70:1 a 5,73:1 selon la nuance de carte). Trois autres fichiers de la
  // vitrine portaient la meme encre en dur : tous passent par ce role.
  identityOnSurface: [color.primaryBlack, color.primaryLight], // 18,13:1 / 5,7:1
  // FOND d'un bouton d'action. D6 (2026-09-09) y posait le navy en clair ; D14
  // (William, 2026-09-13) le rend au bleu de marque dans les DEUX thèmes, en
  // lisant le logo : le J navy structure, le C bleu agit. `#0077CC` est aussi la
  // seule couleur de la palette qui tienne à mi-clarté sur les deux fonds. Le
  // rôle reste le point unique : les boutons pleins le lisent, la décision se
  // rejoue ici et nulle part ailleurs. LE PIÈGE qui vaut toujours : ne PAS
  // reprendre `identityOnSurface` sous prétexte qu'il porte le même navy — c'est
  // une ENCRE, et sa moitié sombre employée comme FOND porte du blanc à 3,12:1.
  // Un couple se choisit par son EMPLOI, pas par sa teinte.
  // Roadmap charte-visuelle-juris-connect § D14 (et § D6 pour l'historique).
  bgAction: [color.primary, color.primary], // 4,66:1 / 4,66:1 (blanc dessus)
  // Encre primaire pour texte posé sur un LAVIS primaire léger (fond
  // `withOpacity(color.primary, 0.05-0.1)`) : primary #0077CC n'y tient plus
  // (4.26:1 sur le lavis, sous AA). Encre plus foncée en light (primaryDark,
  // ~6.7:1 sur le lavis) + primaryLight en dark (~6.4:1 sur le lavis sombre).
  // Session-front 2026-07-14 — bouton « Sources », badges sur lavis primaire.
  primaryOnLavis: [color.primaryStrong, color.primaryLight], // #005799 / #3399DD sur lavis
  /* REMPLISSAGE, PAS ENCRE — et c'est toute la différence avec les deux couples
     ci-dessus. Une jauge, une barre de progression, un segment de graphe occupent
     une SURFACE : leur seuil est 3 contre le fond qu'ils recouvrent (WCAG 1.4.11),
     et ce qu'on leur demande est de se VOIR, pas de se lire. Les couples d'encre
     y donnent des valeurs calibrées pour la lecture — #005799 en clair, soit le
     bleu assourdi d'un texte — et la barre cesse de ressembler à de la marque.
     Né le 2026-09-11, d'un audit de mon propre correctif : j'avais posé
     `primaryOnSurface` en fond de la jauge de rétroplan. L'arithmétique passait
     (5,44 / 5,63 contre la piste) et c'est ce qui rend la faute durable — rien ne
     crie, et le jour où l'encre de lecture est retouchée, la jauge suit sans
     raison. Mesuré avec ce couple : 4,42 en clair, 5,63 en sombre.
     LE SUFFIXE N'EST PAS DÉCORATIF : `theme-contrast.test.ts` classe par lui, et
     il a refusé la première version de ce jeton — nommée `primaryVividOnSurface`,
     donc jugée comme une encre, 4,08:1. `*Fill` a sa catégorie, seuil 3. */
  primaryVividFill: [color.primary, color.primaryLight], // #0077CC / #3399DD
  // L'encre sombre etait `color.errorLight` #E62719, annote « 4.8:1 » — un
  // chiffre qui n'a jamais ete exact : 4,22:1 sur le fond de page et 3,57:1 sur
  // les cartes. C'etait le pire ecart du design system. `errorTextGlass` est le
  // rouge deja calibre pour les fonds sombres (7,01:1).
  // Le versant CLAIR passe de `color.error` a `color.errorText` le 2026-08-24.
  // Il etait la SEULE encre du systeme a valoir sa propre teinte : `success` et
  // `warning` ont chacune leur version assombrie, `error` n'en avait pas. Sur
  // son lavis a 8 % (#f2dfe0) le rouge vif ne vaut que 4,39:1 — le badge
  // « Urgente » de la liste des taches a ete mesure au DOM a 4,38:1.
  // `errorText` (#B71C1C) rend 5,13:1, la fourchette de ses deux voisins.
  // `dangerOnSurface` renomme `errorOnSurface` le 2026-09-22 : seule des trois
  // familles d'etat a ne pas partager son prefixe avec sa palette. Raison du
  // choix et cas ou l'alternative gagnait : message du commit de fondation.
  errorOnSurface: [color.errorText, color.errorTextGlass], // 5,13:1 / 7,01:1
  magentaOnSurface: [color.magentaStrong, color.magentaLight], // #B82F5D (5:1) / #E66BA0 (6.6:1)
  /* LES DEUX COUPLES ETAIENT IDENTIQUES jusqu'au 2026-09-09 — tous deux
     [#00736A, #00C0B5]. La marque et l'etat partageaient donc leur encre dans
     les DEUX modes, et pas seulement leur valeur de base.

     La separation (arbitrage William, banc `/showroom/vert-d-etat`) leur donne
     chacun sa paire, SANS creer de couleur : les quatre valeurs existaient. */
  /* ÉMERAUDE depuis le 2026-09-19 (choix William sur la page des vingt-quatre
     verts) : success #00755E sur clair (5,67:1), successLight #00B894 sur
     sombre (7,15:1 sur la nuit, 6,33 sur une carte). Avant : #00736A / #33D3CA,
     qui n'étaient que le turquoise à deux clartés — et #33D3CA était AUSSI
     secondaryLight : en sombre, « confirmé » et « à débloquer » portaient le
     même pixel. */
  successOnSurface: [color.success, color.successLight], // #00755E (5,67:1) / #00B894 (7,15:1)
  /* SUR UNE SURFACE INVERSÉE (2026-09-17) — une barre `background: themeColor.text`,
     sombre en clair et claire en sombre. Tout rôle « OnSurface » y est à
     contre-thème : `successOnSurface` y rendait 1,51:1 en sombre (le montant du
     pied de CaseEntriesDrawer). La paire MIROIR, sans créer de couleur :
     successLight sur la barre claire (#14171C → 9,68:1), successText sur la barre
     sombre (#e4e8ee → 4,67:1). Dix fichiers posent une barre de ce genre ; le
     banc des tokens ne juge PAS ce rôle — ses fonds de référence sont ceux de la
     page, l'inverse de ceux-ci. */
  successOnInverse: [color.successLight, color.success],
  /* AQUAMARINE N'A PAS DE COUPLE, ET C'EST UN CHOIX (2026-09-22, demande de
     William). Aucun de ses quatre jetons ne passe sur fond clair — 1,31 · 1,28
     · 2,10 · 1,23 sur blanc — donc un `*OnSurface` promettrait une bascule qui
     n'existe pas : en clair elle serait REMPLACEE, pas adaptee. Et `OnInverse`
     designe ici une paire MIROIR, alors que le hero et la visio sont sombres
     dans les DEUX themes. Les deux membres sont donc identiques : la valeur ne
     change pas parce que le FOND ne change pas. Croquis :
     roadmap/charte-visuelle-juris-connect/croquis/2026-09-22-aquamarine-accent-des-surfaces-sombres.md */
  accentSurSombre: [color.aquamarine, color.aquamarine],
  /* La moitie sombre ne peut pas etre `color.success` : a 23 % de clarte il
     rend 3,2:1 sur le fond de nuit. `successLight` y rend 7,15:1. */

  // Turquoise de MARQUE utilise comme encre (badges d'etape, accents studio).
  // Sa moitie claire etait `successText`, l'encre de l'ETAT : la marque
  // empruntait donc sa couleur a un autre domaine. `secondaryDeep` est le teal
  // profond de la marque, cree le 2026-08-31 pour porter du blanc a 6,15:1.
  secondaryOnSurface: [color.secondaryDeep, color.secondary], // #006E64 (6,15:1) / #00C0B5 (8,33:1)
  /* Mêmes valeurs que le couple ci-dessus, et c'est VOULU : le marqueur des
     services à forfait doit pouvoir bouger sans emporter la marque, et
     réciproquement. Fusionner les deux rendrait le prochain arbitrage sur l'un
     invisible sur l'autre — exactement ce qui vient d'arriver au vert d'état.
     § D13 · ADR-PVD-001. */
  premiumBusinessOnSurface: [color.premiumBusinessInk, color.premiumBusiness],
  /* FACE SOMBRE ÉCLAIRCIE D'UN CRAN LE 2026-09-17 (C4) : `warning` (#F57C00) rendait
     4,32:1 sur un voile d'alerte à 14 % posé sur la surface élevée (« En pause »
     des paiements) et 4,61 sur un voile à 18 %. `warningLight` (#FF9933) y rend
     5,85, et 8,92 / 7,54 sur bg / surface — le scope visio faisait déjà ce
     recalibrage (« warningLight, déjà au DS »). Même teinte, un cran plus vif. */
  warningOnSurface: [color.warningText, color.warningLight], // #944B00 (6,43:1, 5,04 sur voile) / #FF9933 (8,92 bg · 7,54 surface · 5,85 sur voile)
  purpleOnSurface: [color.purpleStrong, color.purpleLight], // #7A2E96 (6,92:1) / #CE92E0 (5,88:1) — mauve depuis le 2026-09-20
  // L'encre de Juris-IA — le rôle du violet choisi le 2026-09-20 (voir `ia`
  // dans color.ts). Encre sur clair, cran clair sur sombre.
  iaOnSurface: [color.iaInk, color.iaLight], // #4C3BC7 (6,67:1) / #9C91F0 (5,16:1)
  // L'encre de Verbatim — voir `verbatim` dans color.ts (2026-10-06).
  verbatimOnSurface: [color.verbatimInk, color.verbatimLight], // #6315E7 (6,59:1) / #AE86F4 (5,02:1)
  // LES SEPT COULEURS DE DISTINCTION (2026-09-19) — encre sur clair, vif ou
  // cran clair sur sombre. Le vif est une couleur de SURFACE ; en texte ou en
  // glyphe sur un fond clair, l'ambre fait 2,15:1, l'ocean 2,43, la prairie
  // 2,54 — leurs encres passent 4,5 sur les sept fonds clairs du banc (pire :
  // 4,70 pour l'ocean sur gray100). Sur les huit fonds
  // sombres, le vif tient pour l'ambre, l'ocean et la prairie (6,53 · 5,77 ·
  // 5,53) et pas pour les quatre autres (3,73 · 3,97 · 2,98 · 2,90) : elles
  // prennent leur cran clair (5,07 · 5,29 · 5,70 · 5,52). Regle de la famille
  // dans `color.distinction` : jamais seule, jamais un sens.
  amberOnSurface: [color.distinction.amberInk, color.distinction.amber], // #A94E07 (4,87:1) / #F59E0B (6,53:1)
  brickOnSurface: [color.distinction.brickInk, color.distinction.brickLight], // #B91C1C (5,67:1) / #F87171 (5,07:1)
  roseOnSurface: [color.distinction.roseInk, color.distinction.roseLight], // #BE185D (5,29:1) / #F472B6 (5,29:1)
  orchidOnSurface: [color.distinction.orchidInk, color.distinction.orchidLight], // #86198F (7,22:1) / #E879F9 (5,70:1)
  oceanOnSurface: [color.distinction.oceanInk, color.distinction.ocean], // #0E7490 (4,70:1) / #06B6D4 (5,77:1)
  meadowOnSurface: [color.distinction.meadowInk, color.distinction.meadow], // #047857 (4,81:1) / #10B981 (5,53:1)
  slateOnSurface: [color.distinction.slateInk, color.distinction.slateLight], // #374151 (9,03:1) / #9CA3AF (5,52:1)
  // LES HUITIEME ET NEUVIEME TEINTES prennent leur VIF a gauche, et ce n'est
  // pas un raccourci : l'outremer rend 8,07 et le grenat 9,19 en encre au pire
  // des sept fonds clairs. Un cran `Ink` distinct serait deux noms pour un
  // pixel — le defaut qu'on vient de retirer a `violet`.
  outremerOnSurface: [color.distinction.outremer, color.distinction.outremerLight], // #0606EF (8,07:1) / #9292FC (5,17:1)
  grenatOnSurface: [color.distinction.grenat, color.distinction.grenatLight], // #7B143A (9,19:1) / #E977A1 (5,09:1)
  sienneOnSurface: [color.distinction.sienne, color.distinction.sienneLight], // #76432D (7,05:1) / #D08A6A (5,02:1) — 10e teinte, 2026-09-21
  // Or : comme le jaune, intrinsequement illisible en TEXTE sur clair — #D4A000
  // fait 2,26:1 sur le gris des cartes (mesure du 2026-08-28, « 287 € » a 28 px)
  // et meme goldDark #B38600 plafonne a ~3,1:1. Meme route que caseTaskOnSurface :
  // l'encre orangee foncee en light, l'or vif en dark ; l'identite « or » reste
  // portee par les fonds et les icones, qui gardent la teinte vive.
  /* La moitié claire était `warningText` — 5,58:1, mais à 30° quand l'or est à
     45°. Le contraste était bon, la TEINTE fausse : un texte « or » sortait
     orange. `goldInk` tient 5,50 dans la famille de l'or (2026-09-10). */
  /* « LES ICÔNES GARDENT LA TEINTE VIVE » — TRANCHÉ LE 2026-09-12, ET LA CLAUSE
     TIENT, mais pas pour la raison qu'on pourrait croire. L'or vif mesure 2,38:1
     sur blanc, 2,26 sur #F7F9FC et 2,18 sur le gris des cartes : sous les 3:1
     que WCAG 1.4.11 demande. La clause n'est pourtant pas une entorse, parce que
     ce critère ne vise QUE les objets graphiques « nécessaires à la
     compréhension du contenu ».
     Les sept icônes or du dépôt ont été relues une à une : toutes accompagnent
     un libellé qui dit la même chose — « Badges obtenus », « Classement
     National », « Espace Ambassadeur », « Top X % », un titre de résultat, une
     carte qui nomme son école. Leur sens est redit par le texte : ce sont des
     glyphes de décoration, et le critère ne s'y applique pas.
     L'EXCEPTION EXISTE, ET ELLE EST NOMMÉE : la porte « Performance » de
     l'auvent avocat n'affiche QUE son glyphe au repos — son nom n'apparaît qu'au
     survol. Rien ne le redit, donc l'icône porte l'information, donc 3:1
     s'applique. Elle seule est passée à `goldStrong` (3,32 / 3,15 / 3,04 selon la
     surface). Le test à rejouer sur tout nouvel emploi : *un texte visible dit-il
     déjà ce que cette icône dit ?* */
  goldOnSurface: [color.goldInk, color.gold], // #856400 (5,50:1) / #D4A000 (7,53:1)
  // Jaune : intrinsequement illisible en TEXTE sur blanc (meme yellowDark #B59600
  // ne fait que 2.9:1). On route le label vers une encre orangee foncee lisible
  // en light et le jaune vif en dark ; l'identite "tache" reste portee par la
  // bordure/le fond/l'icone jaune (non textuels, donc conserves vifs).
  caseTaskOnSurface: [color.warningText, color.yellow], // #944B00 (6,43:1) / #FFC107 (9.85-11.65:1 selon surface)
  // Texte info sur fond PALE teinte (StatusTag info/blue/processing) : le
  // #0077CC vif ne fait que 3.88:1 sur infoPale light et 3.01:1 sur son
  // equivalent dark (axe SERIOUS, CQ 2026-07-06) → encre foncee en light,
  // bleu clair en dark. Meme doctrine que *OnSurface (identite = fond/bordure).
  // ÉCLAIRCI côté dark le 2026-08-08 : `infoLight` (#3399DD) rend 4,47:1 sur le
  // lavis bleu du mode sombre — trois centièmes sous le seuil, donc un échec
  // qu'aucun œil ne voit. La correction de 2026-07-06 avait bien identifié le
  // problème et choisi la bonne famille de bleu, simplement un cran trop bas.
  // `primaryLighter` y rend 6,07 et reste la même teinte.
  // Mesuré sur le tag d'expertise de l'annuaire, mais le token porte tous les
  // tags bleus de l'application.
  //
  // RENOMMÉ `primaryOnPale` le 2026-09-20 : William a fondu la famille `info`
  // dans `primary` (« primary sert pour les info », 2026-09-19) — six jetons
  // aux valeurs identiques, deux noms pour un pixel. Le rôle garde SA paire :
  // sa face sombre est `primaryLighter`, pas `primaryLight` — il ne se fond
  // pas dans `primaryOnSurface` (4,47 sur le lavis bleu sombre, cf. ci-dessus).
  primaryOnPale: [color.primaryStrong, color.primaryLighter], // #005799 (~6.2:1) / #66B3E6 (6.07:1)

  // Le pendant sombre du cyan manquait. `cyanText` a été créé le 2026-08-18
  // pour écrire sur cyanPale en thème CLAIR (4,88:1 sur blanc) et y remplit son
  // office — mais il est fixe, et sur les fonds sombres il retombe à 3,89 /
  // 3,59 / 3,29:1 (bg, surface, elevated). Mesuré en production le 2026-08-21
  // sur /app/paiements : « Consult. dossier » à 3,59:1.
  // `cyanLight` y rend 9,94 / 9,17 / 8,40:1 et garde la même identité turquoise.
  // `cyanTextStrong` et non `cyanText` : ce dernier tenait sur blanc et sur le
  // voile cyan, mais retombait à 4,28:1 sur `gray100` — trouvé le jour même en
  // étendant le banc aux fonds gris, quelques heures après avoir créé ce couple.
  secondaryOnPale: [color.secondaryDeep, color.secondaryLight], // #0A6E6E (5,31:1) / #36CFCF (8,4-9,9:1)

  // Le bleu de l'État (badge « avocat.fr » de la file de vérification) était
  // posé FIXE en encre : `gouvBlue` (#000091) rend 14,9:1 sur blanc et 1,27:1
  // sur le fond sombre ; `gouvBlueBright` (#8b8bff), fixe lui aussi dans la
  // variante sombre du même badge, rend 2,90:1 en clair. Chacun avait la bonne
  // valeur pour UN thème — le couple les réunit. Mesuré le 2026-09-17 (C4).
  gouvOnSurface: [color.gouvBlue, color.gouvBlueBright], // #000091 (14,9:1) / #8b8bff (6,54 bg · 5,53 surface)

  // ============================================
  // BORDERS
  // ============================================
  border: [color.border, color.borderDark],
  borderLight: [color.borderLight, color.borderLightDark],
  /**
   * Bordure SUBTILE theme-aware : blackAlpha08 en light (discrète, quasi
   * invisible), whiteAlpha15 en dark (visible). C'est LA bordure qui « dessine »
   * un élément quand sa surface hôte a le même fond que lui (ex. un tag/badge
   * gray50 sur une carte gray50). Une bordure noire fixe (blackAlpha08) disparaît
   * en dark ; themeColor.border (#A8A8A8) est trop marquée en light. D'où ce token.
   */
  borderSubtle: [color.blackAlpha08, color.whiteAlpha15],
  /**
   * Bordure d'ACCENT — celle d'une action qu'on veut voir ressortir de ses
   * voisines, pas s'y fondre. Le pendant de `borderSubtle`, et son exact
   * miroir : là où l'une doit s'effacer, celle-ci doit dépasser.
   *
   * MÊME PIÈGE, MÊME REMÈDE. Posée en couleur FIXE
   * (`withOpacity(color.slateBlueDark, 0.28)`), elle tenait son rôle en clair —
   * 1,53:1 contre 1,24 pour la bordure voisine, donc elle ressortait — et le
   * PERDAIT en sombre : 1,25:1 contre 1,40 pour `borderDark`, c'est-à-dire
   * MOINS visible que ce dont elle devait se distinguer. L'intention
   * s'inversait exactement là où l'écran est le plus avare de contraste.
   *
   * LE VOISIN EST LE MÊME RÔLE DANS LES DEUX THÈMES (2026-09-23). La valeur se
   * juge contre le trait courant `border`, voisin réel de ses deux consommateurs
   * (la touche de raccourci d'`AideLigneAction`, le séparateur des portes de la
   * reprise). En clair l'accent pèse 0,67× ce trait et ressort par sa TEINTE ;
   * en sombre il doit peser pareil, à 0,15 près — sinon l'élément change
   * d'importance en changeant de thème. Le banc `border-accent-contraste` le
   * garde, et il ne reste vert qu'entre 0,29 et 0,35 d'opacité sombre.
   *
   * ⚠ NE PAS « RECALIBRER » SUR LA RÈGLE PRÉCÉDENTE. Elle reproduisait le
   * rapport à « la bordure voisine », mais comparait `blackAlpha08` en clair à
   * `borderDark` en sombre : deux objets, qui pesaient pareil (1,19 et 1,40:1)
   * tant que les filets sombres étaient sous-dosés. L'arbitrage du 2026-09-22 a
   * remis `borderDark` au cran de `border` (2,24:1) ; appliquer l'ancienne règle
   * pousserait l'opacité sombre à 0,60 et l'accent AU-DESSUS du trait courant,
   * en sombre seulement. C'est le principe qui fixe la valeur, pas le goût — à
   * condition de comparer un objet à lui-même.
   *
   * Trouvé le 2026-08-20 en auditant `AideLigneAction`, par CALCUL : mélange de
   * la couleur à son fond selon l'opacité, puis formule WCAG. Une bordure
   * décorative n'a pas de seuil AA à tenir — ce qui se vérifie ici est un écart
   * relatif, pas un plancher.
   */
  borderAccent: [
    withOpacity(color.distinction.sienne, 0.28),
    withOpacity(color.distinction.sienneLight, 0.35),
  ], // 1,59:1 sur blanc / 1,80:1 sur surfaceDark — sienne depuis le 2026-09-21 ; 0,67× puis 0,80×
  // le trait courant `border` (2,38 et 2,24:1) : la même place dans la rampe des deux thèmes.
  /**
   * CONTRASTES MESURÉS 2026-08-07, sur blanc — les trois côte à côte, parce qu'un
   * chiffre faux ici a des conséquences loin d'ici :
   *   borderLight #D0D0D0 → 1,54  ·  border #A8A8A8 → 2,38  ·  borderStrong #909090 → 3,19 ✅
   *
   * Employer `borderStrong` — et lui seul — quand la bordure DÉLIMITE un élément
   * interactif (bouton, champ, carte cliquable) : elle porte alors du sens, et le
   * seuil de 3:1 de WCAG 1.4.11 s'applique. `border` reste juste pour ce qui
   * sépare ou encadre sans rien signifier.
   * (L'ancien commentaire annonçait borderStrong à « ~2,3:1 » — la valeur de
   * `border`, recopiée par erreur. Personne ne va chercher un token annoncé sous
   * le seuil pour régler un problème de seuil : ça l'a rendu introuvable.)
   *
   * Les ratios ne sont plus annotés ici : `theme-contrast.test.ts` les mesure sur
   * le pire fond de chaque thème. Ce paragraphe annonçait « en sombre le seuil
   * n'est pas atteint, #2A4A6E → 1,76, arbitrage laissé ouvert » ; le token a été
   * éclairci deux fois depuis, et cette phrase restait un argument valable pour ne
   * rien faire. Une mesure écrite au présent et sans date se lit comme une
   * propriété du système — personne ne la reteste.
   *
   * Il affirmait aussi que `borderStrong` borde les overlays : FAUX, et contredit
   * sept lignes plus bas. Sa portée réelle est celle des CHAMPS et des éléments
   * interactifs. J'ai propagé cette phrase dans `color.ts`, un commit et un
   * registre avant de la mesurer.
   */
  borderStrong: [color.borderStrong, color.borderStrongDark],
  /**
   * Bordure CANONIQUE des surfaces flottantes (dropdown, popover, menu, picker).
   * Toute bulle flottante référence ce token ; un ajustement se fait ici.
   *
   * C'est LUI, pas `borderStrong`, qui borde les overlays — les deux partagent
   * leur valeur claire depuis l'assombrissement du 2026-06-10, ce qui les fait
   * passer pour interchangeables. Ratios tenus par le banc.
   *
   * La valeur claire pointe désormais sur `borderStrong` (#808080) et non plus
   * sur `gray500` (2026-08-21). Elle valait la même chose — les deux étaient à
   * #909090 — mais `gray500` porte 516 usages dans le dépôt : assombrir CE
   * token-là pour réparer une bordure aurait déplacé une teinte partout ailleurs.
   * Les deux entrées restent DISTINCTES, précisément pour qu'on puisse corriger
   * l'une sans l'autre — c'est l'erreur du 2026-06-10, où le mauvais des deux
   * avait été touché en croyant traiter les overlays.
   */
  overlayBorder: [color.borderStrong, color.gray500Dark],
  cardBorder: [color.cardBorder, color.cardBorderDark],
  divider: [color.divider, color.dividerDark],

  // ============================================
  // GRAYS (inversent completement en dark mode)
  // ============================================
  gray50: [color.gray50, color.gray50Dark],
  gray100: [color.gray100, color.gray100Dark],
  gray200: [color.gray200, color.gray200Dark],
  gray300: [color.gray300, color.gray300Dark],
  gray400: [color.gray400, color.gray400Dark],
  /* LES DEUX PAS DU MILIEU SONT DES ENCRES, ET LEUR FACE CLAIRE NE TENAIT PAS
     (2026-09-17). `themeColor.gray500` pose une encre dans 173 de ses 231 lignes
     d'usage, `gray600` dans 34 sur 57 (mesuré ce jour-là). Or `color.gray500`
     rend 3,20:1 sur blanc et 2,80 sur `gray100` ; `color.gray600` 4,26 et 3,73 —
     sous 4,5 sur TOUS les fonds clairs, dans 158 + 34 fichiers, sans qu'aucun
     banc ne le dise : celui des tokens ne jugeait que les rôles `text*` et
     `*OnSurface`.
     La face SOMBRE avait déjà été courbée pour la même raison le 2026-08-09
     (`gray500Dark = gray600Dark = #8a9ab0`, « un gris de moins dans la palette »).
     Même geste ici : les deux faces claires prennent `gray700` (#606D7D), le pas
     le plus clair de l'échelle qui tient 4,5:1 partout — 5,28 sur blanc, 4,62 sur
     `gray100` et `subtle`. Ne PAS assombrir `color.gray500` / `color.gray600`
     eux-mêmes : les usages figés les reçoivent aussi en sombre (voir la note sur
     `color.gray600`, 43 pages empirées pour 21 le 2026-08-09).
     Ce que ça coûte, et qu'on assume : en clair, `gray500`, `gray600` et
     `gray700` rendent la même valeur. Six fichiers posent `gray500` ET `gray600`
     en encre comme deux niveaux — ils n'en ont plus qu'un ; huit fonds `gray500`
     (rails, poignées, tirettes) s'assombrissent d'un cran. */
  gray500: [color.gray700, color.gray500Dark],
  gray600: [color.gray700, color.gray600Dark],
  gray700: [color.gray700, color.gray700Dark],
  gray800: [color.gray800, color.gray800Dark],
  gray900: [color.gray900, color.gray900Dark],

  // ============================================
  // SEMANTIC (white/black inversent)
  // ============================================
  white: [color.white, color.whiteDark],
  black: [color.black, color.blackDark],

  // ============================================
  // BACKGROUND ALPHA (semi-transparent backgrounds)
  // Light = subtle dark tint on white | Dark = subtle light tint on dark
  // High values (90+) = nearly opaque backgrounds matching theme
  // ============================================
  bgAlpha04: [color.blackAlpha04, color.whiteAlpha04],
  bgAlpha06: [color.blackAlpha06, color.whiteAlpha06],
  bgAlpha10: [color.blackAlpha10, color.whiteAlpha10],
  bgAlpha12: [color.blackAlpha12, color.whiteAlpha12],
  bgAlpha15: [color.blackAlpha15, color.whiteAlpha15],
  bgAlpha20: [color.blackAlpha20, color.whiteAlpha20],
  bgAlpha25: [color.blackAlpha25, color.whiteAlpha25],
  bgAlpha30: [color.blackAlpha30, color.whiteAlpha30],
  bgAlpha90: [color.whiteAlpha90, color.blackAlpha90],
  bgAlpha92: [color.whiteAlpha92, color.blackAlpha90],

  // ============================================
  // OVERLAYS
  // ============================================
  overlay: [color.overlay, color.overlayDark],
  overlayLight: [color.overlayLight, color.overlayLightDark],
  overlayStrong: [color.overlayStrong, color.overlayStrongDark],
  backdrop: [color.backdrop, color.backdropDark],

  // ============================================
  // SHADOWS (plus prononcees en dark mode)
  // ============================================
  shadowSm: [color.shadows.sm, color.shadows.smDark],
  shadowBase: [color.shadows.base, color.shadows.baseDark],
  shadowMd: [color.shadows.md, color.shadows.mdDark],
  shadowLg: [color.shadows.lg, color.shadows.lgDark],
  shadowXl: [color.shadows.xl, color.shadows.xlDark],
} as const;

type ThemeKey = keyof typeof themeMap;

function generateVars(mode: "light" | "dark"): string {
  const idx = mode === "light" ? 0 : 1;
  return Object.entries(themeMap)
    .map(([key, values]) => `--theme-${key}: ${values[idx]};`)
    .join("\n    ");
}

/**
 * Les variables du theme CLAIR, pour les redefinir sur un SOUS-ARBRE.
 *
 * Le ThemeProvider ecrit sur `document.body` : l'imbriquer basculerait toute
 * l'application, pas seulement la zone visee. Or il existe un cas ou l'on veut
 * exactement l'inverse — l'apercu « Ma vitrine », qui doit montrer a l'avocat ce
 * que SON CLIENT verra, c'est-a-dire du clair, meme quand lui travaille en
 * sombre. Un apercu qui suit le theme de celui qui regarde rate sa raison
 * d'etre.
 *
 * Les variables etant heritees en CSS, les redefinir sur un conteneur suffit :
 * tout ce qui vit dedans repasse en clair, le reste de l'ecran ne bouge pas.
 *
 * A n'utiliser QUE pour un apercu d'une surface dont le theme ne depend pas du
 * lecteur. Partout ailleurs, c'est le ThemeProvider qui decide.
 */
export const VARIABLES_THEME_CLAIR = generateVars("light");

/**
 * Le pendant sombre — il manquait, et son absence se voyait ailleurs.
 *
 * Le clair etait exportable depuis longtemps, le sombre non : AUCUN banc du
 * showroom ne montrait donc les deux themes cote a cote. Le sombre etait un
 * citoyen de seconde classe par accident d'API, pas par decision.
 *
 * Poser l'attribut de theme sur une div NE SUFFIT PAS : les variables generees
 * vivent sous un selecteur qui commence par body, il ne descend pas. Seule la
 * redefinition sur le conteneur porte l'heritage (cf. le scope visio, plus bas).
 * Meme reserve que pour le clair : un apercu, jamais l'app.
 */
export const VARIABLES_THEME_SOMBRE = generateVars("dark");

/**
 * Global CSS qui definit les CSS custom properties de theme.
 * A rendre UNE SEULE FOIS dans le ThemeProvider.
 */
export const GlobalThemeStyle = createGlobalStyle`
  body, body[data-theme="light"] {
    ${generateVars("light")}

    /* PAS de color-scheme ici : c'est ThemeContext qui le pose, en JS, sur
       documentElement — le seul element dont il gouverne le fond du canvas.
       Le declarer sur body serait redondant et trompeur (retrait 2026-09-03,
       apres une correction fondee sur une sonde qui basculait a moitie). */

    /* Idem en clair : Ant en dérive #0077CC, 4,18 sur lavis bleu pâle.
       Les onglets ne sont pas repris ici parce qu'ils ne se règlent pas ici —
       StyledTabs les peint dans les DEUX thèmes (voir le bloc sombre). */
    [class*="css-var-"] {
      --ant-color-link: var(--theme-primaryOnSurface);
      --ant-color-link-hover: var(--theme-primaryOnSurface);
    }
  }
  body[data-theme="dark"] {
    ${generateVars("dark")}


    /* Existaient, mais dans le scope VISIO — donc inertes ailleurs (3,03). */
    .ant-form-item-optional,
    .ant-form-item-extra,
    .ant-form-item-explain:not(.ant-form-item-explain-error) {
      color: var(--theme-textSecondary) !important;
    }

    /* LE BLEU DES LIENS NUS — et pourquoi le token ne suffit PAS.
       Le ConfigProvider pose bien colorLink en sombre. Ça ne change rien :
       l'algorithme d'Ant RECALCULE colorLink depuis colorPrimary après coup, et
       c'est sa valeur dérivée qui atterrit dans la variable CSS. Mesuré au
       niveau de la variable elle-même :

         .css-var-r0 { --ant-color-link: #2e85bf }     <- l'algorithme
         token.colorLink = primaryLight (#3399DD)      <- ignoré

       Éprouvé en poussant colorLink à une valeur criarde : le lien n'a pas
       bougé d'un pixel. Un token qu'on pose et qui n'agit pas est pire qu'un
       token absent — il ferme la question.

       Résultat au rendu : 4,18 sur fond clair et 4,20 sur fond nuit, sous le
       seuil AA de 4,5, sur tous les liens nus de l'application.

       La restriction aux liens SANS attribut class vise exactement le cas en
       défaut. Sans ce garde, la spécificité (0-1-1) l'emporterait sur tout
       styled-component (0-1-0), et cette règle repeindrait des liens que leur
       composant avait déjà décidés. */
    /* On NOURRIT la variable d'Ant. token.colorLink est recalculé par son
       algorithme ; une règle plus spécifique, même en !important, perd. Une
       custom property se résout au plus proche ancêtre qui la déclare. */
    [class*="css-var-"] {
      --ant-color-link: var(--theme-primaryOnSurface);
      --ant-color-link-hover: var(--theme-primaryOnSurface);

      /* ONGLETS — un filet, PAS le décideur. Ces lignes ne servent qu'aux Tabs
         rendus SANS notre wrapper : dès que StyledTabs enveloppe le composant,
         c'est lui qui peint (Ant déclare via :where(), spécificité zéro ; un
         styled-component vaut 0-1-0, plus un !important). Mesuré : la variable
         valait bien #3399DD pendant que l'onglet rendait #0077CC — la nourrir
         n'avait rien changé. Un onglet illisible se corrige dans StyledTabs.
         La barre d'encre n'est pas reprise : aplat d'identité, elle reste vive. */
      --ant-tabs-item-selected-color: var(--theme-primaryOnSurface);
      --ant-tabs-item-hover-color: var(--theme-primaryOnSurface);
    }
  }

  /* Scope de thème SOMBRE FORCÉ pour le parcours visio (chantier
     parcours-visio-best-in-class, décision user 2026-07-05 : tout le parcours
     — salle d'attente, room, post-call — rend en ambiance studio sombre,
     indépendamment du thème global de l'app, sans switch light/dark exposé).
     Les CSS custom properties sont redéfinies sur ce scope → tous les
     descendants utilisant themeColor.* (var(--theme-*)) héritent du sombre.
     La specificity body vs [data-visio-theme] ne s'oppose pas : chaque règle
     cible un élément distinct, l'héritage prend l'ancêtre le plus proche. */
  [data-visio-theme="dark"] {
    ${generateVars("dark")}
    color-scheme: dark;

    /* RECALIBRAGE VERRE (2026-07-12, signale par William : « la police grise sur
       fond presque noir c'est pas evident »). Les valeurs dark ci-dessus sont
       calibrees pour un fond dark OPAQUE (#0A1117). Le studio, lui, empile des
       surfaces de VERRE translucide (whiteAlpha08/10) par-dessus le gradient :
       le fond effectif remonte a ~#2b3a3e (mesure AU PIXEL sur le rendu reel) et
       les ratios chutent SOUS le seuil WCAG AA 4.5:1. Avant -> apres, sur le fond
       de verre le plus clair :
         textSecondary     4.12:1 ❌ -> 6.65:1 ✅
         textTertiary      2.78:1 🔴 -> 5.10:1 ✅
         primaryOnSurface  3.79:1 ❌ -> 5.15:1 ✅  (primaryLighter, deja au DS)
         warningOnSurface  4.37:1 ❌ -> 5.55:1 ✅  (warningLight,  deja au DS)
       successOnSurface (#00C0B5 = 5.18:1) tient deja -> on n'y touche pas.
       ⚠ axe-core est AVEUGLE ici : sur un fond en gradient il classe en
       "incomplete", PAS en "violation" (faux vert). Re-mesurer AU PIXEL via
       front/e2e/_visio-contrast-audit.mjs, jamais via un scan axe seul.
       ⚠ Pas de backtick dans ce commentaire : on est DANS le template literal
       de createGlobalStyle (un backtick le refermerait). */
    --theme-textSecondary: ${color.secondaryTextGlass};
    --theme-textTertiary: ${color.tertiaryTextGlass};
    --theme-primaryOnSurface: ${color.primaryLighter};
    --theme-warningOnSurface: ${color.warningLight};
    /* Surcharge ECRITE A LA MAIN, quand les variables de base sont generees
       (l. 901). Renommer la cle sans cette ligne l'aurait rendue muette. */
    --theme-errorOnSurface: ${color.errorTextGlass};
    /* Le turquoise tient sur le verre NEUTRE (5.18:1) mais pas sur un fond
       TEINTE de sa propre couleur — le badge « Camera OK » pose son encre sur
       un fond success a 14% : 4.09:1, sous AA. successLight y remonte a 5.02:1
       (et gagne aussi sur fond neutre : 6.36:1). */
    --theme-successOnSurface: ${color.successLight};
    --theme-secondaryOnSurface: ${color.secondaryLight};

    /* ANT DESIGN ECHAPPE AU SCOPE — rattachement force.
       Ant resout ses tokens en CSS-in-JS depuis le ConfigProvider (theme GLOBAL)
       et injecte une couleur EN DUR dans ses classes : .ant-typography-secondary
       n'a jamais vu nos CSS vars. Resultat mesure : dans le studio, un
       <Text type="secondary"> affichait #6b6b70 en theme clair et #6a7a90 en
       sombre (= le token du theme de l'app) sur le fond noir -> 2.37:1 a 3.01:1,
       tres en dessous de AA. Le bug etait INVISIBLE tant qu'on n'auditait qu'en
       theme sombre : d'ou l'audit des DEUX themes (e2e/_visio-contrast-audit.mjs).
       12 <Text type="secondary"> + 4 "warning" + 1 "success" concernes.
       !important : necessaire pour battre la specificite du CSS-in-JS d'Ant. */
    .ant-typography-secondary,
    .ant-typography.ant-typography-secondary {
      color: var(--theme-textSecondary) !important;
    }
    .ant-typography-warning,
    .ant-typography.ant-typography-warning {
      color: var(--theme-warningOnSurface) !important;
    }
    .ant-typography-success,
    .ant-typography.ant-typography-success {
      color: var(--theme-successOnSurface) !important;
    }

    /* MÊME MÉCANISME, sur le Tag par défaut. Un Tag sans couleur explicite rend
       la classe ant-tag-filled et tire son fond d'un token que Tag.defaultBg
       n'atteint pas : il reste au gris tertiaire du mode clair, sous une encre
       claire.
       Le defaultColor du même bloc s'applique, LUI — c'est ce qui rend le cas
       trompeur : la moitié de la configuration prend, l'autre non.
       PORTÉE RÉELLE : cette règle couvre les Tag d'Ant employés NUS. Elle a été
       posée en croyant corriger les tags de /webinaires — ils portaient en fait
       un styled-component local qui figeait son propre fond, et c'est là que le
       correctif a eu lieu. Un !important ne bat pas un composant qui pose la
       même propriété plus bas dans la cascade : quand une règle globale ne prend
       pas, la cause est presque toujours locale.
       (Aucun backtick ici : dans un template literal, il le FERME. Piège
       reproduit deux fois dans la journée, dont une en le documentant.) */
    /* QUATRIÈME du même genre, après Typography, Tag et Collapse : les deux
       textes auxiliaires d un champ de formulaire. « (optionnel) » et le texte
       d aide sous un champ ne lisent ni colorTextDescription ni
       colorTextPlaceholder — ils gardaient le gris du mode clair, 3,03:1.
       Le patron est maintenant clair : dès qu un composant Ant a un texte
       SECONDAIRE, vérifier au rendu qu il reçoit bien la couleur du thème. La
       configuration ne suffit pas à le dire. */
    .ant-form-item-optional,
    .ant-form-item-extra,
    .ant-form-item-explain:not(.ant-form-item-explain-error) {
      color: var(--theme-textSecondary) !important;
    }

    /* MÊME MÉCANISME sur l en-tête de Collapse. Le bloc sombre du
       ConfigProvider pose bien headerBg, mais un Collapse rendu sans bordure
       (bordered={false}) n en tire pas son fond : il restait blanc sous une
       encre claire, 1,23:1. Mesuré sur les FAQ des simulateurs — 25 cas.
       C est le troisième composant Ant du même genre, après Typography et Tag :
       la clé est présente, le variant ne la lit pas. */
    .ant-collapse-borderless > .ant-collapse-item > .ant-collapse-header,
    .ant-collapse-ghost > .ant-collapse-item > .ant-collapse-header,
    .ant-collapse-borderless > .ant-collapse-item,
    .ant-collapse-borderless .ant-collapse-content {
      background: var(--theme-surface) !important;
      color: var(--theme-text) !important;
    }
    .ant-collapse-borderless .ant-collapse-header-text,
    .ant-collapse-ghost .ant-collapse-header-text {
      color: var(--theme-text) !important;
    }

    .ant-tag:not([class*="ant-tag-"]):not([style*="background"]),
    .ant-tag-filled:not([class*="ant-tag-has-color"]) {
      background: var(--theme-bgElevated) !important;
      color: var(--theme-text) !important;
      border-color: var(--theme-border) !important;
    }
    .ant-typography-danger,
    .ant-typography.ant-typography-danger {
      color: var(--theme-errorOnSurface) !important;
    }
  }

  /* P1: Smooth theme transition (disabled on first load via data-theme-hint).
     Bug fix 2026-04-23 : retrait du selecteur universel *, *::before, *::after
     qui ECRASAIT toutes les transition-property des composants enfants via
     specificity (0,1,1) > styled-component (0,1,0). Consequence : aucune
     transition custom (max-height, transform, opacity...) ne fonctionnait car
     le shorthand transition reset transition-property a la liste des 4. Fix :
     on applique la transition au body uniquement, qui anime son background ;
     les enfants changent instantanement lors d'un theme switch (acceptable car
     simultane avec le body) mais gardent leurs propres transitions UI intactes. */
  body[data-theme] {
    transition: background-color 0.25s ease, color 0.2s ease, border-color 0.25s ease, box-shadow 0.25s ease;
  }

  /* Disable THEME transitions during page load to prevent flash.
     Only targets background/color/border — NOT transform, opacity, etc.
     Bug fix 2026-03-21: the previous rule used "transition: none !important"
     which killed ALL transitions on the client subdomain (no ThemeProvider). */
  html[data-theme-hint] body:not([data-theme]) * {
    transition-property: background-color, color, border-color, box-shadow !important;
    transition-duration: 0s !important;
  }

  /* Respect reduced-motion preference — only disable animations, not transitions.
     transform/opacity transitions are UI feedback, not decorative motion. */
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
    }
  }

  /* ============================================
     SURFACES FLOTTANTES ANT — bordure visible sur fond blanc (2026-05-31)
     ============================================
     Par defaut les popups Ant (Dropdown / Select / Picker / Cascader) n'ont
     QU'une ombre + colorBgElevated, SANS bordure -> "inexistante" sur le fond
     blanc du site (user feedback "je ne vois pas la bordure du dropdown qui
     s'ouvre"). On force la bordure CANONIQUE des surfaces flottantes via le
     token overlayBorder (#909090, cf themeMap BORDERS).

     ANTI-REGRESSION ("a l'avenir") : cette regle est GLOBALE (GlobalThemeStyle
     montee a la racine main.tsx), donc appliquee PARTOUT — lawyer/admin/client
     + showroom (route top-level hors LawyerLayout) + TOUT futur popup Ant,
     automatiquement, sans dependance au layout ni override cas par cas.
     (Les popups Ant sont portales dans <body> qui porte --theme-overlayBorder.)
     Les surfaces flottantes custom (styled.div MenuContainer, overlays inline)
     referencent themeColor.overlayBorder — meme token, 1 source de verite. */
  .ant-dropdown-menu,
  .ant-select-dropdown,
  .ant-picker-panel-container,
  .ant-cascader-menus {
    border: var(--border-thin) solid var(--theme-overlayBorder);
  }

  /* ============================================
     PREFERENCES UTILISATEUR — page /app/parametres/general (refonte 2026-05-10)
     ============================================
     Les data-attributes sont poses sur body par useGeneralPreferencesEffects
     (cf shared/hooks/useGeneralPreferencesEffects.ts) selon le store
     useGeneralPreferencesStore. Approche compatible avec le bug fix
     2026-04-23 : on cible *-duration / *-iteration-count uniquement,
     PAS le shorthand "transition" qui ecraserait les transition-property
     des styled-components enfants. */

  /* Animations OFF — toggle "Animations" dans Apparence + alias dans Accessibilite. */
  body[data-animations="off"], body[data-animations="off"] *,
  body[data-animations="off"] *::before, body[data-animations="off"] *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  /* Focus visible amplifie — outline 4px primary + offset + halo 8px.
     Aide accessibilite WCAG 2.4.7 + RGAA 7.1 pour navigation clavier.
     Renforcement 2026-05-10 PM : avant 3px+halo 6px etait trop subtle,
     beaucoup de composants stylized:focus ecrasaient. Maintenant on
     cible aussi *:focus (pas que focus-visible) pour couvrir les
     elements legacy + on ajoute un decalage outline et un fond accent. */
  body[data-focus-amplified="true"] *:focus,
  body[data-focus-amplified="true"] *:focus-visible {
    outline: 4px solid #0077CC !important;
    outline-offset: 3px !important;
    box-shadow:
      0 0 0 4px #ffffff,
      0 0 0 8px rgba(0, 119, 204, 0.45) !important;
    border-radius: 6px !important;
  }
  body[data-focus-amplified="true"][data-theme="dark"] *:focus,
  body[data-focus-amplified="true"][data-theme="dark"] *:focus-visible {
    box-shadow:
      0 0 0 4px #000000,
      0 0 0 8px rgba(0, 119, 204, 0.55) !important;
  }
  /* Empeche les reset 'outline:none' des Ant Design Buttons quand le
     focus amplifie est actif. */
  body[data-focus-amplified="true"] button:focus,
  body[data-focus-amplified="true"] a:focus,
  body[data-focus-amplified="true"] [tabindex]:focus {
    outline: 4px solid #0077CC !important;
    outline-offset: 3px !important;
  }

  /* Contraste eleve — pousse les ratios WCAG AA -> AAA SANS mode "brouillon
     imprime en gras". Ratios cibles AAA : 7:1 texte courant, 4.5:1 large.
     Approche : assombrir le texte secondaire (gris clair illisible) + texte
     tertiaire + bordures-light (presque invisibles) sans toucher au texte
     principal ni au font-weight (qui rendraient la page agressive).

     Renforcement 2026-05-10 PM : avant override agressif noir pur partout
     + font-weight 500 + bordures 2px + liens soulignes. User feedback
     "c'est pas un peu trop eleve ?" -> niveau intermediaire AAA confortable. */
  body[data-contrast="high"] {
    /* Texte principal : passe de #12181B (deja AAA) -> on ne touche pas. */
    /* Texte secondaire : passe de #6B6B70 (AA 4.6:1) -> #3a3a3a (AAA 9:1). */
    /* Noms en camelCase — les vars sont générées via --theme-<key> (cf .map plus
       haut) depuis les clés camelCase du themeMap. En kebab (--theme-text-secondary)
       le contraste ne s'appliquait PAS (mismatch = bouton « œil » sans effet). */
    --theme-textSecondary: #3a3a3a;
    --theme-textTertiary: #4a4a4a;
    /* Bordures : passe de #C8C8C8 (3:1) -> #6B6B70 (4.6:1) pour visibilite
       sans surcharger l'ecran. */
    --theme-border: #6B6B70;
    --theme-borderLight: #909090;
    --theme-divider: #909090;
  }
  /* Liens dans le texte : underline permanent mais discret (1px). Sans
     ca, en flat design tres pur, les liens deviennent indistinguables du
     texte. Avec underline -> repere visuel non-couleur. */
  body[data-contrast="high"] a:not([role="button"]):not(.ant-btn) {
    text-decoration: underline;
    text-underline-offset: 2px;
  }
  body[data-contrast="high"][data-theme="dark"] {
    --theme-textSecondary: #d8d8d8;
    --theme-textTertiary: #c0c0c0;
    --theme-border: #909090;
    --theme-borderLight: #6B6B70;
    --theme-divider: #6B6B70;
  }

  /* Texte agrandi (« Confort de lecture » du parcours signataire —
     SignAccessibilityToggle). Le design utilise px() (pixels fixes) donc la propriete
     zoom est la voie propre pour TOUT agrandir d'un coup (texte + boutons + document).
     L'attribut data-sign-scale n'est pose que sur la page /sign (set/remove au montage
     du toggle) donc effet scope, aucune pollution ailleurs. */
  body[data-sign-scale="lg"] {
    zoom: 1.15;
  }
  body[data-sign-scale="xl"] {
    zoom: 1.3;
  }
`;

/**
 * Tokens theme-aware pour styled-components.
 *
 * Referencent des CSS custom properties qui basculent automatiquement.
 * Utiliser pour surfaces, textes, bordures — PAS pour les brand colors.
 *
 * @example
 * background: ${themeColor.bg};        // blanc en light, #1E1E1E en dark
 * color: ${themeColor.text};            // #12181B en light, #F1F1F1 en dark
 * border-color: ${themeColor.border};   // #A8A8A8 en light, #2C2C2C en dark
 * box-shadow: ${themeColor.shadowMd};   // ombre legere en light, plus forte en dark
 */
export const themeColor = Object.fromEntries(
  Object.keys(themeMap).map((key) => [key, `var(--theme-${key})`]),
) as Record<ThemeKey, string>;
